import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";

import {
  replaceGeneratedConstants,
  replaceGeneratedCss,
  rewriteGeneratedBlock,
} from "./generate-step-palette.mjs";

const CONSTANTS_FIXTURE = `export const OUTPUT_DEFAULT_LABELS = {} as const;

/** Generated by scripts/generate-step-palette.mjs. */
export const STEP_COLOR_PALETTES = {
  rainbow: {
    dark: ["#000000"],
    light: ["#ffffff"],
  },
} as const;

// ============================================================================
// NEXT SECTION
// ============================================================================
export const AFTER = 1;
`;

const CSS_FIXTURE = `@import "tailwindcss";

/* Generated by scripts/generate-step-palette.mjs. */
:root {
  --fp-step-hue-0: #000000;
}

body.vscode-light,
body.vscode-high-contrast-light {
  --fp-step-hue-0: #ffffff;
}

/* ============================================================================
   Base Layer
   ============================================================================ */
`;

function writeFixture(name, content, eol) {
  const path = join(mkdtempSync(join(tmpdir(), "step-palette-")), name);
  writeFileSync(path, eol === "\n" ? content : content.split("\n").join(eol));
  return path;
}

// A CRLF working copy — a Windows checkout, or an editor that re-saved the
// file — used to abort `precompile` with "could not find the generated block",
// because the anchors are written with LF.
for (const [name, eol] of [
  ["LF", "\n"],
  ["CRLF", "\r\n"],
]) {
  test(`rewrites the generated constants block in a ${name} file`, () => {
    const path = writeFixture("DashboardConstants.ts", CONSTANTS_FIXTURE, eol);

    rewriteGeneratedBlock(path, replaceGeneratedConstants);

    const rewritten = readFileSync(path, "utf8");
    assert.match(rewritten, /rainbow: \{/);
    assert.match(rewritten, /export const AFTER = 1;/);
    assert.equal(rewritten.includes("#000000"), false);
    assertLineEndings(rewritten, eol);
  });

  test(`rewrites the generated css block in a ${name} file`, () => {
    const path = writeFixture("globals.css", CSS_FIXTURE, eol);

    rewriteGeneratedBlock(path, replaceGeneratedCss);

    const rewritten = readFileSync(path, "utf8");
    assert.match(rewritten, /--fp-step-hue-47:/);
    assert.match(rewritten, /Base Layer/);
    assertLineEndings(rewritten, eol);
  });
}

test("still rejects a file whose generated block is gone", () => {
  const path = writeFixture(
    "DashboardConstants.ts",
    "export const A = 1;\n",
    "\n"
  );

  assert.throws(
    () => rewriteGeneratedBlock(path, replaceGeneratedConstants),
    /Could not find the generated step palette block/
  );
});

/** The rewrite must not leave the file mixing both endings. */
function assertLineEndings(source, eol) {
  assert.equal(source.includes("\r\n"), eol === "\r\n");
  assert.equal(source.replace(/\r\n/g, "").includes("\r"), false);
}
